const canvasReadOnlyTools = new Set<ToolName>([
    "canvas_read_quality_reports",
    "canvas_preflight_image_edit",
    "canvas_get_state", "canvas_get_drawing", "canvas_get_context", "canvas_get_capabilities", "canvas_list_open_canvases", "canvas_find_nodes", "canvas_find_available_assets", "canvas_preflight_storyboard_media", "canvas_preflight_batch_rows", "canvas_get_node",
    "canvas_get_connection", "canvas_get_generation_tasks", "canvas_get_resources", "canvas_validate_ops",
    "canvas_get_selection", "canvas_export_snapshot", "canvas_get_storyboard",
    "canvas_get_timeline",
    "canvas_list_director_scenes", "canvas_get_director_scene",
    "canvas_list_projects", "canvas_export_projects",
    "canvas_batch_table_read",
    "canvas_inspect_node_render",
]);

export const toolInputSchemas: Record<ToolName, z.AnyZodObject> = { ...baseToolInputSchemas };
for (const name of toolNames) {
    if (name.startsWith("film_") || name.startsWith("project_")) {
        toolInputSchemas[name] = toolInputSchemas[name].extend(canvasReadSelector);
    }
}
const canvasWritePreconditions = {
    expectedCanvasId: z.string().min(1),
    expectedRevision: z.number().int().nonnegative(),
    expectedStateHash: z.string().min(1),
};
for (const name of toolNames) {
    if (name.startsWith("canvas_") && !canvasReadOnlyTools.has(name)) {
        toolInputSchemas[name] = toolInputSchemas[name].extend(canvasWritePreconditions);
    }
}

