for (const name of toolNames) {
    if (name.startsWith("canvas_") && !canvasReadOnlyTools.has(name)) {
        toolDescriptions[name] += " 本画布写操作必须显式提供 expectedCanvasId、expectedRevision、expectedStateHash；从 canvas_get_context.canvas.projectId 与状态字段取值，画布不匹配或状态已变化时会拒绝执行。";
    }
}
